    const txt='NISHANT CHAKRAVARTHY  ✦  CREATIVE DEVELOPER  ✦  ';let w=x.measureText(txt).width,sc=2048/(Math.round(2048/w)*w);x.scale(sc,1);for(let ox=0;ox<2048/sc;ox+=w)x.fillText(txt,ox,50);
