/* ---------- UI bits tied to scenes ---------- */
const dots=$('#dots');PROJECTS.forEach((p,i)=>{const d=document.createElement('i');dots.appendChild(d);});
$('#pTot').textContent=String(PROJECTS.length).padStart(2,'0');
function showProject(i){const p=PROJECTS[i],t=$('#pTitle');t.classList.add('swap');
  setTimeout(()=>{t.textContent=p.t;t.classList.remove('swap');},180);
  $('#pIdx').textContent=String(i+1).padStart(2,'0');$('#pYear').textContent=p.y;$('#pDesc').textContent=p.d;
  $('#pTags').innerHTML=(p.team?'<span class="team">Team project</span>':'')+p.tags.map(x=>`<span>${x}</span>`).join('');$('#pMetrics').innerHTML=p.m.map(([v,l])=>`<div><b>${v}</b><small>${l}</small></div>`).join('');$('#pLink').href=p.url;$('#pLink').firstChild.textContent=p.cta||(p.k==='wire'?'More on GitHub ':'View on GitHub ');
  [...dots.children].forEach((d,j)=>d.classList.toggle('on',j===i));
  const sh=$('#pShot'),u=window.__posterURL?window.__posterURL(i):'';sh.classList.toggle('has',!!u);sh.setAttribute('aria-label',p.t+' project preview');
  if(u){sh.classList.add('swap');setTimeout(()=>{sh.style.backgroundImage='url('+u+')';sh.classList.remove('swap');},180);}}
showProject(0);
$$('a[href="#credentials"]').forEach(l=>['pointerenter','touchstart','focus'].forEach(ev=>l.addEventListener(ev,()=>window.__credLoad&&window.__credLoad(),{passive:true,once:true})));
(()=>{const sh=$('#pShot');let x0=null;sh.addEventListener('touchstart',e=>{x0=e.touches[0].clientX;},{passive:true});
  sh.addEventListener('touchend',e=>{if(x0==null)return;const dx=e.changedTouches[0].clientX-x0;x0=null;if(Math.abs(dx)>40)$(dx<0?'#next':'#prev').click();});
  (document.readyState==='complete'?f=>f():f=>addEventListener('load',f))(()=>setTimeout(()=>{if(matchMedia('(max-width:640px)').matches)showProject(+$('#pIdx').textContent-1);},600));})();
const mBtns=$('#mBtns');FORMS.forEach((f,i)=>{const b=document.createElement('button');b.type='button';b.textContent=f.n;b.setAttribute('data-hover','');b.addEventListener('click',e=>{e.stopPropagation();if(gl&&gl.setForm)gl.setForm(i);else showForm(i);});mBtns.appendChild(b);});
function showForm(i){$('#mIdx').textContent='0'+(i+1);$('#mName').textContent=FORMS[i].n;$('#mDesc').textContent=FORMS[i].d;[...mBtns.children].forEach((b,j)=>b.classList.toggle('on',j===i));}
