/* ---------- fit giant words to the screen ---------- */
function fit(){$$('.page .big').forEach(b=>{b.style.fontSize='';const W=b.clientWidth;let m=0;b.querySelectorAll('.split').forEach(s=>{m=Math.max(m,s.scrollWidth);});if(m>W&&W>0){const fs=parseFloat(getComputedStyle(b).fontSize);b.style.fontSize=(fs*W/m*.97)+'px';}});}
fit();addEventListener('resize',fit);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(fit);

/* ---------- router with soft fade ---------- */
const PAGES=['home','work','about','credentials','contact'];
const HINTS={home:'Move your mouse · click the blob',work:'Drag · scroll · click a card',about:'Click to change form',credentials:'Hover a certificate · click to view',contact:'Move · click to ripple'};
var cur_page=null;window.__page=()=>cur_page;
function show(name,first){
  $$('.page').forEach(p=>{p.classList.toggle('on',p.id===name);p.classList.remove('shown','leaving');});
  cur_page=name;if(gl)gl.setScene(name);$('#ticker').classList.toggle('on',name==='home');
  $$('nav ul a').forEach(a=>{const on=a.getAttribute('href')==='#'+name;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  if(!first)$('#announce').textContent=(name==='home'?'Home':name[0].toUpperCase()+name.slice(1))+' page';
  const n=PAGES.indexOf(name)+1;$('#pgNum').textContent='0'+n;$('#pgBar').style.setProperty('--p',(n/PAGES.length*100)+'%');
  $('#hint').textContent=HINTS[name];lab.classList.toggle('on',name==='work');lab.textContent='Drag';
  document.title=(name==='home'?'Portfolio':name[0].toUpperCase()+name.slice(1))+' — Nishant Chakravarthy';
  requestAnimationFrame(()=>requestAnimationFrame(()=>$('#'+name).classList.add('shown')));
}
let busy=false;
function navigate(){
  const name=PAGES.includes(location.hash.slice(1))?location.hash.slice(1):'home';
  if(name===cur_page||busy)return;
  if(reduce||cur_page===null){show(name,cur_page===null);return;}
  busy=true;const v=$('#veil'),old=$('#'+cur_page);
  old.classList.add('leaving');old.classList.remove('shown');
  document.body.classList.add('switching');v.classList.add('on');
  setTimeout(()=>{show(name);document.body.classList.remove('switching');v.classList.remove('on');},420);
  setTimeout(()=>{busy=false;if((location.hash.slice(1)||'home')!==cur_page)navigate();},760);
}
addEventListener('hashchange',navigate);
addEventListener('keydown',e=>{if(e.target.closest('input,textarea'))return;const i=PAGES.indexOf(cur_page);
  if(cur_page==='work'&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){$(e.key==='ArrowRight'?'#next':'#prev').click();return;}
  if(e.key==='ArrowDown'||e.key==='PageDown')location.hash=PAGES[Math.min(i+1,PAGES.length-1)];
  if(e.key==='ArrowUp'||e.key==='PageUp')location.hash=PAGES[Math.max(i-1,0)];});


/* ---------- intro: 3D particle portrait + glowing GREETINGS, waits for a click ---------- */
window.__introActive=true;
(function intro(){
  const L=$('#loader'),cv=$('#introGL'),cap=$('#introCap'),enter=$('#enter'),cnt=$('#count'),fb=$('#greetFallback');
  if(matchMedia('(hover:none)').matches)$('#enterHint').textContent='Tap anywhere to enter';
  let finished=false,ready=false,warmed=false,tOut=null,raf=0,R=null,start=0;
  const ease=x=>x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2, out3=x=>1-Math.pow(1-x,3), clamp=x=>Math.max(0,Math.min(1,x));
  function finish(){if(finished)return;finished=true;
    if(gl&&gl.prepareEntry){gl.prepareEntry();gl.setScene('home');}window.__introActive=false;setTimeout(()=>navigate(),700);
    L.classList.add('done');document.body.classList.add('entering');setTimeout(()=>document.body.classList.remove('entering'),3500);
    requestAnimationFrame(()=>document.body.classList.remove('pre-enter'));
    setTimeout(()=>{cancelAnimationFrame(raf);if(R)R.dispose();L.remove();},2600);}
  function requestEnter(){if(!ready||tOut!==null)return;if(gl&&gl.warm&&!warmed){warmed=true;gl.warm();}tOut=start?(performance.now()-start)/1000:0;L.classList.add('leaving');enter.classList.remove('on');cap.classList.remove('on');if(!R)finish();}
  L.addEventListener('click',requestEnter);
  L.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();requestEnter();}});
  const fontsReady=document.fonts&&document.fonts.load?Promise.race([Promise.all([document.fonts.load('400 120px Italiana'),document.fonts.load('400 12px "JetBrains Mono"')]),new Promise(r=>setTimeout(r,1800))]):Promise.resolve();

  const ME_SRC="portrait-particles.png";
  /* front surface from the sculpted depth map; back and sides from the silhouette */
  function loadMe(N){return new Promise(res=>{const img=new Image();img.onload=()=>{try{
      const W=img.width,H=img.height,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');x.drawImage(img,0,0);
      const d=x.getImageData(0,0,W,H).data;const SH=2.95,SW=SH*W/H,S=SH/H,ZM=140;
      const Lr=new Float32Array(H),Rr=new Float32Array(H);
      for(let y=0;y<H;y++){let l=-1,r=-1;for(let xx=0;xx<W;xx++){if(d[(y*W+xx)*4+3]>128){if(l<0)l=xx;r=xx;}}Lr[y]=l;Rr[y]=r;}
      const fac=y=>{const t=y/H,hw=(Rr[y]-Lr[y])/2;return hw>W*.29?.3:t<.5?1.3:.9;};
      const backZ=(fx,y)=>{if(Lr[y]<0)return 0;const cx=(Lr[y]+Rr[y])/2,hw=Math.max((Rr[y]-Lr[y])/2,1),u=(fx-cx)/hw;return -fac(y)*hw*Math.sqrt(Math.max(0,1-u*u))*S;};
      const pos=new Float32Array(N*3),lum=new Float32Array(N);let k=0,guard=0;
      const nFront=N,nBack=0;
      while(k<nFront&&guard<N*80){guard++;const fx=Math.random()*W,fy=Math.random()*H,i=((fy|0)*W+(fx|0))*4;
        if(d[i+3]<128)continue;const Lu=d[i]/255,Z=d[i+1]/255*ZM*S,E=d[i+2]/255;
        if(Math.random()>.18+.55*Lu+.8*E)continue;
        pos[k*3]=(fx/W-.5)*SW;pos[k*3+1]=2.1-fy*S;pos[k*3+2]=-backZ(fx,fy|0)*.22+(Math.random()-.5)*.012;lum[k]=Math.min(1,Math.max(Lu,E*.95));k++;}
      while(k<nFront+nBack&&guard<N*120){guard++;const fx=Math.random()*W,fy=Math.random()*H,y=fy|0,i=(y*W+(fx|0))*4;
        if(d[i+3]<128)continue;pos[k*3]=(fx/W-.5)*SW;pos[k*3+1]=2.1-fy*S;pos[k*3+2]=backZ(fx,y);lum[k]=.06+Math.random()*.1;k++;}
      while(k<N&&guard<N*160){guard++;const y=(Math.random()*H)|0;if(Lr[y]<0)continue;const side=Math.random()<.5?Lr[y]:Rr[y];
        const zf=d[(y*W+(side|0))*4+1]/255*ZM*S,zb=backZ(side+(side===Lr[y]?1:-1),y),t=Math.random();
        pos[k*3]=(side/W-.5)*SW;pos[k*3+1]=2.1-(y+Math.random())*S;pos[k*3+2]=zb+(zf-zb)*t;lum[k]=.1+Math.random()*.14;k++;}
      res(k>N*.8?{pos:pos.subarray(0,k*3),lum:lum.subarray(0,k),n:k}:null);}catch(e){res(null);}};
    img.onerror=()=>res(null);img.src=ME_SRC;});}

  function greetTexture(){const c=document.createElement('canvas');c.width=2048;c.height=360;const x=c.getContext('2d');
    x.font='400 250px Italiana, Didot, serif';x.textBaseline='middle';const txt='GREETINGS',sp=46;
    let w=0;for(const ch of txt)w+=x.measureText(ch).width+sp;w-=sp;let px=(2048-w)/2;
    const g=x.createLinearGradient(0,40,0,320);g.addColorStop(0,'#ffffff');g.addColorStop(.55,'#efe9df');g.addColorStop(1,'#b9b2a6');
    x.fillStyle=g;x.shadowColor='rgba(255,90,60,.55)';x.shadowBlur=40;
    for(const ch of txt){x.fillText(ch,px,190);px+=x.measureText(ch).width+sp;}
    const t=new THREE.CanvasTexture(c);t.anisotropy=8;return t;}

  function startGL(me){
    if(!window.THREE)return false;
    try{
      const small=innerWidth<700;
      R=new THREE.WebGLRenderer({canvas:cv,antialias:true,powerPreference:'high-performance'});
      R.setPixelRatio(Math.min(devicePixelRatio,small?1.5:2));R.setClearColor(0x050505,1);
      const scene=new THREE.Scene(),cam=new THREE.PerspectiveCamera(32,1,.1,100);
      let composer=null,bloom=null;
      if(THREE.EffectComposer&&THREE.UnrealBloomPass){try{composer=new THREE.EffectComposer(R);composer.addPass(new THREE.RenderPass(scene,cam));
        bloom=new THREE.UnrealBloomPass(new THREE.Vector2(innerWidth,innerHeight),small?.75:.95,.6,.32);composer.addPass(bloom);}catch(e){composer=null;}}
      const fit=()=>{R.setSize(innerWidth,innerHeight,false);if(composer)composer.setSize(innerWidth,innerHeight);cam.aspect=innerWidth/innerHeight;cam.updateProjectionMatrix();};fit();addEventListener('resize',fit);

      /* GREETINGS: a glowing plane behind the figure, revealed left to right */
      const gU={map:{value:greetTexture()},uReveal:{value:0},uOp:{value:0},uT:{value:0}};
      const greet=new THREE.Mesh(new THREE.PlaneGeometry(1,360/2048),new THREE.ShaderMaterial({uniforms:gU,transparent:true,depthWrite:false,
        vertexShader:SHADERS['intro-greet.vert'],
        fragmentShader:SHADERS['intro-greet.frag']}));
      greet.position.set(0,1.62,-1.7);scene.add(greet);

      /* the portrait */
      let N=small?26000:60000,target,lumA;if(me){target=me.pos;lumA=me.lum;N=me.n;}else{target=bust(N);lumA=new Float32Array(N).fill(.7);}
      const startP=new Float32Array(N*3),rand=new Float32Array(N);
      for(let i=0;i<N;i++){const u=Math.random()*2-1,a=Math.random()*Math.PI*2,s=Math.sqrt(1-u*u),r=5+Math.random()*7;startP[i*3]=s*Math.cos(a)*r;startP[i*3+1]=u*r*.7+1.4;startP[i*3+2]=s*Math.sin(a)*r-1;rand[i]=Math.random();}
      const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(target,3));g.setAttribute('aStart',new THREE.BufferAttribute(startP,3));g.setAttribute('aRand',new THREE.BufferAttribute(rand,1));g.setAttribute('aLum',new THREE.BufferAttribute(lumA,1));
      const U={uProg:{value:0},uOut:{value:0},uT:{value:0},uPR:{value:R.getPixelRatio()},uSize:{value:small?12:10.5},uScan:{value:-1},uVis:{value:0}};
      const pts=new THREE.Points(g,new THREE.ShaderMaterial({uniforms:U,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,
        vertexShader:SHADERS['intro-portrait.vert'],
        fragmentShader:SHADERS['intro-portrait.frag']}));
      const grp=new THREE.Group();grp.add(pts);scene.add(grp);

      /* floating dust for depth */
      const DN=small?500:1100,dp=new Float32Array(DN*3);for(let i=0;i<DN;i++){dp[i*3]=(Math.random()-.5)*12;dp[i*3+1]=Math.random()*6-1.5;dp[i*3+2]=(Math.random()-.5)*8;}
      const dg=new THREE.BufferGeometry();dg.setAttribute('position',new THREE.BufferAttribute(dp,3));
      const dust=new THREE.Points(dg,new THREE.PointsMaterial({size:.018,color:0xffb4a0,transparent:true,opacity:.35,depthWrite:false,blending:THREE.AdditiveBlending}));scene.add(dust);

      /* the spark that ignites the face, and the shockwave when it locks in */
      const spark=new THREE.Sprite(new THREE.SpriteMaterial({map:(()=>{const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');const g=x.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.18,'rgba(255,200,170,.9)');g.addColorStop(.45,'rgba(255,70,40,.35)');g.addColorStop(1,'rgba(255,40,20,0)');x.fillStyle=g;x.fillRect(0,0,128,128);return new THREE.CanvasTexture(c);})(),transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,opacity:0}));
      spark.position.set(0,1.5,.4);spark.scale.setScalar(.01);scene.add(spark);
      const shock=new THREE.Mesh(new THREE.RingGeometry(.97,1,160),new THREE.MeshBasicMaterial({color:0xff7a5c,transparent:true,opacity:0,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide}));
      shock.position.set(0,1.25,0);scene.add(shock);
      const shock2=shock.clone();shock2.material=shock.material.clone();scene.add(shock2);
      const look=new THREE.Vector3();
      start=performance.now();
      function frame(){const t=(performance.now()-start)/1000;
        U.uT.value=t;gU.uT.value=t;
        /* timeline: GREETINGS holds the stage alone, then the face slowly lights up from the eyes outward */
        const T1=reduce?0:3.6,T2=reduce?0:3.6,T3=reduce?0:7.2;
        U.uVis.value=1;
        U.uProg.value=reduce?1:clamp((t-T2)/(T3-T2));
        const port=cam.aspect<1,zEnd=port?7.6:4.7,textY=1.62,lyEnd=port?1.0:1.12;
        const ph1=reduce?1:out3(clamp(t/T1)),ph2=reduce?1:ease(clamp((t-T2)/(T3-T2+.6)));
        const push=tOut===null?0:ease(clamp((t-tOut)/2.2))*1.8;
        let z=(zEnd+.9-.3*ph1)-.6*ph2-push,ly=textY+(lyEnd-textY)*ph2;
        const breathe=Math.sin(t*1.1)*.012;
        cam.position.set(mouse.x*.12,ly+.06+mouse.y*.08+breathe,z);look.set(0,ly,0);cam.lookAt(look);
        grp.rotation.y+=((mouse.x*.1+Math.sin(t*.45-.6)*.06)-grp.rotation.y)*.05;
        grp.rotation.x+=((-mouse.y*.04)-grp.rotation.x)*.05;
        /* GREETINGS: revealed alone, then softens as the face lights up */
        const dist=z+1.7,visW=2*dist*Math.tan(THREE.MathUtils.degToRad(16))*cam.aspect;greet.scale.setScalar(Math.min(visW*.9,7.2));
        gU.uReveal.value=reduce?1.15:clamp((t-.3)/2.0)*1.15;
        gU.uOp.value=(reduce?1:clamp((t-.2)/.9))*(1-.45*ph2)*(tOut===null?1:1-clamp((t-tOut)/.5));
        /* a faint warm glow gathers behind the eyes just before the face ignites */
        const pre=clamp((t-T1+1.0)/1.0),post=clamp((t-T2-.4)/1.4);spark.material.opacity=reduce?0:pre*(1-post)*.55;spark.scale.setScalar(.2+pre*.8+post*.6);spark.position.set(0,1.62,.35);
        shock.material.opacity=0;shock2.material.opacity=0;
        /* bloom rises gently with the light, then settles */
        if(bloom&&tOut===null)bloom.strength=(small?.75:.95)+.55*Math.sin(Math.PI*clamp((t-T2)/(T3-T2+.8)));
        /* a light scan sweeps down the body once it has formed */
        const sc=((t-T3-.6)%3.6)/1.6;U.uScan.value=t>T3+.6&&sc<1?2.15-sc*3.2:-9;
        dust.rotation.y=t*.02;dust.position.y=Math.sin(t*.3)*.05;
        cnt.textContent=String(Math.round(clamp(t/(T3||1))*100)).padStart(3,'0');
        if(t>T3+.3)cap.classList.add('on');
        if(t>T3+.7&&!ready){ready=true;enter.classList.add('on');}
        if(t>T3+1.3&&!warmed){warmed=true;setTimeout(()=>{if(gl&&gl.warm)gl.warm();},0);}
        if(tOut!==null){const k=clamp((t-tOut)/2.2);U.uOut.value=k;if(bloom)bloom.strength=(small?.75:.95)+Math.sin(Math.min(k*1.4,1)*Math.PI)*.9;if(t-tOut>1.15)finish();}
        if(composer)composer.render();else R.render(scene,cam);raf=requestAnimationFrame(frame);}
      frame();return true;
    }catch(e){console.warn('intro 3D off',e);return false;}
  }
  /* simple procedural bust used only if the photo data cannot load */
  function bust(N){const pos=new Float32Array(N*3);for(let i=0;i<N;i++){const u=Math.random()*2-1,a=Math.random()*6.283,s=Math.sqrt(1-u*u),head=i<N*.45;
      pos[i*3]=s*Math.cos(a)*(head?.42:1.15);pos[i*3+1]=head?1.55+u*.56:(u*.8-.2);pos[i*3+2]=s*Math.sin(a)*(head?.5:.4);}return pos;}

  fontsReady.then(()=>loadMe(innerWidth<700?26000:60000)).then(me=>{
    if(!startGL(me)){fb.style.display='block';start=performance.now();setTimeout(()=>cap.classList.add('on'),600);
      setTimeout(()=>{ready=true;enter.classList.add('on');cnt.textContent='100';},1500);}
  });
})();

function trapFocus(m){m.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const f=[...m.querySelectorAll('a[href],button:not([disabled])')].filter(x=>x.offsetParent);if(!f.length)return;const a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}});}
/* ---------- credentials list + certificate viewer ---------- */
(function(){const list=$('#credList');
  list.innerHTML=CREDS.map((c,i)=>`<li><button class="cred-row" type="button" data-i="${i}" data-hover><span class="cr-n">${String(i+1).padStart(2,'0')}</span><span class="cr-main"><span class="cr-kind">${c.kind}</span><b>${c.t}</b><small>${c.iss}</small></span><span class="cr-d">${c.d}</span></button></li>`).join('');
  const rows=[...list.querySelectorAll('.cred-row')];
  window.__credFocus=i=>{rows.forEach((r,j)=>r.classList.toggle('on',j===i));const c=CREDS[i];$('#cfKind').textContent=c.kind+' · '+c.d;$('#cfTitle').textContent=c.t;$('#cfIss').textContent=c.iss;};
  window.__credFocus(0);
  const m=$('#certModal'),img=$('#certImg'),closeB=$('#closeCert');let last=null;
  function open(i,from){const c=CREDS[i];last=from||null;img.src='certs/'+c.k+'.jpg';img.alt=c.alt;$('#certTitle').textContent=c.t;$('#certSub').textContent=c.iss+' · '+c.d;$('#certOpen').href='certs/'+c.k+'.jpg';
    m.hidden=false;requestAnimationFrame(()=>m.classList.add('on'));closeB.focus();}
  window.__openCert=open;
  function close(){m.classList.remove('on');setTimeout(()=>{m.hidden=true;if(last)last.focus();},450);}
  rows.forEach((r,i)=>{r.addEventListener('pointerenter',()=>{window.__credHover=i;if(gl&&gl.credFocus)gl.credFocus(i);window.__credFocus(i);});
    r.addEventListener('pointerleave',()=>{window.__credHover=null;});
    r.addEventListener('focus',()=>{if(gl&&gl.credFocus)gl.credFocus(i);window.__credFocus(i);});
    r.addEventListener('click',()=>open(i,r));});
  closeB.addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close();});
  addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)close();});trapFocus(m);})();

