/* ---------- cursor loop, magnet, copy, clock ---------- */
if(matchMedia('(hover:hover)').matches)(function loop(){px+=(cx-px)*.2;py+=(cy-py)*.2;const X=px.toFixed(1)+'px',Y=py.toFixed(1)+'px';cur.style.setProperty('--x',X);cur.style.setProperty('--y',Y);lab.style.setProperty('--x',X);lab.style.setProperty('--y',Y);requestAnimationFrame(loop);})();
const mag=$('#copy');
let magBase=null;const magMeasure=()=>{const t=mag.style.transform;mag.style.transform='';magBase=mag.getBoundingClientRect();mag.style.transform=t;};
mag.addEventListener('pointerenter',magMeasure);
mag.addEventListener('pointermove',e=>{if(!magBase)magMeasure();const r=magBase;mag.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.35}px,${(e.clientY-r.top-r.height/2)*.35}px)`;});
